<?php require '../config.php';header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}$d=json_decode(file_get_contents('php://input'),true)??$_POST;$email=trim($d['email']??'');$pw=$d['password']??'';$q=$conn->prepare('SELECT id,name,email,password,role FROM users WHERE email=? LIMIT 1');$q->bind_param('s',$email);$q->execute();$u=$q->get_result()->fetch_assoc();if(!$u||!password_verify($pw,$u['password'])){http_response_code(401);echo json_encode(['success'=>false,'message'=>'Invalid email or password.']);exit;}session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];$_SESSION['user_email']=$u['email'];$_SESSION['role']=$u['role'];echo json_encode(['success'=>true,'user'=>['id'=>$u['id'],'name'=>$u['name'],'role'=>$u['role']]]);
